 Json solverValues()const{Json spec={{"objective",address(solverObjective->text())},{"goal",solverGoal->currentData().toString().toStdString()},{"method",solverMethod->currentData().toString().toStdString()},{"variables",Json::array()},{"constraints",Json::array()},{"tolerance",finite(solverTolerance->text(),"Solver tolerance")},{"maxEvaluations",solverEvaluations->value()}};if(spec.at("tolerance").get<double>()<=0||spec.at("tolerance").get<double>()>1)throw std::runtime_error("Solver tolerance must be positive and at most 1.");if(spec.at("method")=="evolutionary"&&solverEvaluations->value()<5)throw std::runtime_error("Evolutionary Solver needs at least 5 evaluations.");const auto seed=solverSeed->text().trimmed();bool okay=false;const auto number=seed.toULongLong(&okay);if(!okay||!QRegularExpression("^[0-9]+$").match(seed).hasMatch()||number>4294967295ULL||(spec.at("method")=="linear"&&number>2147483647ULL))throw std::runtime_error("Enter a nonnegative integer seed within this Solver method's supported range.");spec["seed"]=number;if(spec.at("goal")=="value")spec["target"]=finite(solverTarget->text(),"Solver target");if(variables->rowCount()<1||variables->rowCount()>200)throw std::runtime_error("Choose one to 200 Solver input cells.");std::set<std::string> addresses;for(int row=0;row<variables->rowCount();++row){auto value=address(itemText(variables,row,0));if(!addresses.insert(value.dump()).second)throw std::runtime_error("Solver changing cells must be unique.");for(const auto& entry:std::vector<std::pair<int,const char*>>{{1,"lower"},{2,"upper"},{3,"start"}})if(!itemText(variables,row,entry.first).isEmpty())value[entry.second]=finite(itemText(variables,row,entry.first),entry.second);const int type=static_cast<QComboBox*>(variables->cellWidget(row,4))->currentIndex();value["integer"]=type>0;value["binary"]=type==2;double lower=value.value("lower",-1e20),upper=value.value("upper",1e20);if(type==2){lower=std::max(0.0,lower);upper=std::min(1.0,upper);}if(lower>upper)throw std::runtime_error("Solver variable lower bounds must not exceed upper bounds.");if(spec.at("method")!="linear"&&(!value.contains("lower")||!value.contains("upper")))throw std::runtime_error("Nonlinear and evolutionary Solver inputs need finite lower and upper bounds.");if(value.contains("start")){const double start=value.at("start");if(start<lower||start>upper)throw std::runtime_error("Solver starts must lie within variable bounds.");if(type>0&&std::floor(start)!=start)throw std::runtime_error("Integer and binary input starts must be integer values.");}spec["variables"].push_back(std::move(value));}if(constraints->rowCount()>1000)throw std::runtime_error("Solver supports at most 1,000 constraints.");for(int row=0;row<constraints->rowCount();++row){auto value=address(itemText(constraints,row,0));value["relation"]=static_cast<QComboBox*>(constraints->cellWidget(row,1))->currentText().toStdString();value["value"]=finite(itemText(constraints,row,2),"constraint");spec["constraints"].push_back(std::move(value));}return spec;}
