 void buildGoal(QVBoxLayout* contents){goalPage=new QWidget(editor);auto* layout=new QVBoxLayout(goalPage);layout->setContentsMargins(0,0,0,0);auto* note=new QLabel("Choose a formula output and one numeric input cell. Optional bounds limit the search. Only a converged result can be accepted; a saved setup does not run the calculation.",goalPage);note->setWordWrap(true);layout->addWidget(note);auto* form=new QFormLayout;layout->addLayout(form);goalOutput=line(form,"Formula output","goal.output","A1");goalChanging=line(form,"Changing input cell","goal.changing","A2");goalTarget=line(form,"Target value","goal.target","0");goalStart=line(form,"Start (blank: current input)","goal.start");goalLower=line(form,"Lower bound (optional)","goal.lower");goalUpper=line(form,"Upper bound (optional)","goal.upper");goalTolerance=line(form,"Absolute tolerance","goal.tolerance","1e-9");goalRelativeTolerance=line(form,"Relative tolerance","goal.relativeTolerance","0");goalIterations=budget(form,"Maximum iterations","goal.maxIterations",100);goalEvaluations=budget(form,"Maximum evaluations","goal.maxEvaluations",200);auto* actions=new QHBoxLayout;layout->addLayout(actions);auto* use=button(actions,"Use selected input cell","goal.useSelection");QObject::connect(use,&QPushButton::clicked,owner,[this]{try{goalChanging->setText(reference(selection));}catch(const std::exception& error){owner->setRunState("error",error.what());}});contents->addWidget(goalPage);}
