 void buildAssumptions(QVBoxLayout* contents){typedPage=new QWidget(editor);auto* layout=new QVBoxLayout(typedPage);layout->setContentsMargins(0,0,0,0);auto* note=new QLabel("Set explicit replacement values for input cells. Text stays text, including leading zeros and text beginning with =. Preview applies the selected inputs as one reviewed change.",typedPage);note->setWordWrap(true);layout->addWidget(note);assumptions=table(typedPage,"financial.assumptionCells",{"Input cell","Type","Value"});assumptions->setColumnWidth(0,150);layout->addWidget(assumptions);auto* actions=new QHBoxLayout;layout->addLayout(actions);auto* add=button(actions,"Add input","financial.addInput");auto* remove=button(actions,"Remove input","financial.removeInput");auto* selected=button(actions,"Add selected cell","financial.addSelectedInput");QObject::connect(add,&QPushButton::clicked,owner,[this]{addAssumption(Json());});QObject::connect(remove,&QPushButton::clicked,owner,[this]{if(assumptions->currentRow()>=0)assumptions->removeRow(assumptions->currentRow());});QObject::connect(selected,&QPushButton::clicked,owner,[this]{try{if(!selection.contains("sheet"))throw std::runtime_error("Select a worksheet input cell first.");addAssumption(selection);}catch(const std::exception& error){owner->setRunState("error",error.what());}});contents->addWidget(typedPage);}
 void addAssumption(const Json& value){if(assumptions->rowCount()>=1000){owner->setRunState("error","An assumption set supports up to 1,000 input cells.");return;}const int row=assumptions->rowCount();assumptions->insertRow(row);item(assumptions,row,0,value.is_object()?reference(value):"A1");auto* type=new QComboBox(assumptions);type->setAccessibleName("Assumption value type");for(const auto& entry:std::vector<std::pair<QString,QString>>{{"Number","number"},{"Text","string"},{"Boolean","boolean"},{"Blank","blank"}})type->addItem(entry.first,entry.second);const auto kind=value.is_object()?value.value("type",std::string("number")):"number";type->setCurrentIndex(std::max(0,type->findData(QString::fromStdString(kind))));assumptions->setCellWidget(row,1,type);QString display="0";if(value.is_object()&&value.contains("value")){const auto& input=value.at("value");display=kind=="blank"?QString():input.is_string()?text(input):input.is_boolean()?(input.get<bool>()?"TRUE":"FALSE"):QString::number(input.get<double>(),'g',17);}item(assumptions,row,2,display);assumptions->setCurrentCell(row,0);}
 void showKind(){const bool forecast=kind->currentData()=="forecast",comparison=kind->currentData()=="scenario_comparison",sensitivity=kind->currentData()=="sensitivity",report=forecast||comparison||sensitivity;forecastPage->setVisible(forecast);typedPage->setVisible(kind->currentData()=="scenario"||kind->currentData()=="assumption_set");comparisonPage->setVisible(comparison);sensitivityPage->setVisible(sensitivity);goalPage->setVisible(kind->currentData()=="goal_seek");solverPage->setVisible(kind->currentData()=="solver");outputPage->setVisible(report);if(save){save->setText(report?"Save and preview":"Save setup");save->setAccessibleName(save->text());save->setAccessibleDescription(report?"Accept the result to save the report definition":"Save this reusable setup without running numerical work");}}
